using Xunit;

public class IdadeTests {
    [Theory]
    [InlineData(18, true)]
    [InlineData(16, false)]
    public void EhMaiorDeIdade(int idade, bool esperado) {
        Assert.Equal(esperado, idade >= 18);
    }
}
